def count_active_bombs():
    n = int(input())
    circles = []

    for _ in range(n):
        x, y, r = map(int, input().split())
        circles.append((x, y, r))

    # Set to store points that are inside at least 2 circles
    active_bombs = set()

    # Check all points in the 1000x1000 grid from (1,1) to (1000,1000)
    for x in range(1, 1001):
        for y in range(1, 1001):
            # Count how many circles contain this point
            circle_count = 0
            for cx, cy, cr in circles:
                # Check if (x,y) is on or inside the circle
                distance_squared = (x - cx) ** 2 + (y - cy) ** 2
                if distance_squared <= cr ** 2:
                    circle_count += 1

            # If point is inside at least 2 circles, it's active
            if circle_count >= 2:
                active_bombs.add((x, y))

    return len(active_bombs)

print(count_active_bombs())
